const TONES = {
  light: ["#2E3192", "#00AEEF"],
  dark: ["#3D46CC", "#00C8F7"],
  glow: ["#8FA6FF", "#7FE4FF"],
} as const;

export type BrandTone = keyof typeof TONES;

export function BrandMark({
  tone = "light",
  className,
}: {
  tone?: BrandTone;
  className?: string;
}) {
  const [from, to] = TONES[tone];
  // 같은 페이지에 여러 톤이 함께 놓이므로 그라디언트 id를 톤별로 분리한다
  const gs = `jsm-s-${tone}`;
  const gc = `jsm-c-${tone}`;

  return (
    <svg viewBox="0 0 512 512" className={className} aria-hidden="true" focusable="false">
      <defs>
        <linearGradient
          id={gs}
          gradientUnits="userSpaceOnUse"
          x1="107.726"
          y1="381.361"
          x2="418.83"
          y2="130.643"
        >
          <stop offset="0" stopColor={from} />
          <stop offset="1" stopColor={to} />
        </linearGradient>
        <linearGradient
          id={gc}
          gradientUnits="userSpaceOnUse"
          x1="41.734"
          y1="256.002"
          x2="468.43"
          y2="256.002"
        >
          <stop offset="0" stopColor={from} />
          <stop offset="1" stopColor={to} />
        </linearGradient>
      </defs>
      <path fill={`url(#${gs})`} fillRule="evenodd" d={SPIKES} />
      <path fill={`url(#${gc})`} fillRule="evenodd" d={CAPS} />
    </svg>
  );
}

/**
 * 헤더·푸터 락업.
 * 워드마크는 이미지가 아니라 본문 폰트로 조판한다 — 「지성크리닝」 글자의
 * 벡터 원본이 아직 없고, 통이미지로 넣으면 크기·색 대응이 안 된다.
 */
export function BrandLockup({
  tone = "light",
  showParent = true,
  className = "",
}: {
  tone?: BrandTone;
  showParent?: boolean;
  className?: string;
}) {
  const onDark = tone !== "light";

  return (
    <span className={`flex items-center gap-2.5 ${className}`}>
      {/* 최소 여백 = 심볼 높이의 0.4배. 최소 크기 30px */}
      <BrandMark tone={tone} className="h-8 w-8 shrink-0" />
      <span className="leading-none">
        <span
          className={`block text-[1.3125rem] font-extrabold tracking-[-0.045em] ${
            onDark ? "text-white" : "text-navy"
          }`}
        >
          <T k="brand.name" />
        </span>
        {showParent && (
          <span
            className={`mt-[3px] block text-[0.625rem] font-semibold ${
              onDark ? "text-pale" : "text-muted"
            }`}
          >
            <T k="brand.parent" />
          </span>
        )}
      </span>
    </span>
  );
}
